Here are **both iterative and recursive** versions of **binary search** in simple and clean C code — easy to understand and use in exams or projects.

---

### 🔍 Binary Search (Iterative Version)
```c
int binarySearchIter(int arr[], int n, int key) {
    int low = 0, high = n - 1;

    while (low <= high) {
        int mid = (low + high) / 2;

        if (arr[mid] == key)
            return mid;           // Found
        else if (arr[mid] < key)
            low = mid + 1;        // Search right half
        else
            high = mid - 1;       // Search left half
    }

    return -1;  // Not found
}
```

---

### 🔍 Binary Search (Recursive Version)
```c
int binarySearchRec(int arr[], int low, int high, int key) {
    if (low > high)
        return -1;  // Not found

    int mid = (low + high) / 2;

    if (arr[mid] == key)
        return mid;
    else if (arr[mid] < key)
        return binarySearchRec(arr, mid + 1, high, key);  // Right
    else
        return binarySearchRec(arr, low, mid - 1, key);   // Left
}
```

